$ErrorActionPreference='Stop';$roots=@('backend/src/Fraud/DeviceRisk.Domain','backend/src/Fraud/DeviceRisk.Application','backend/src/Fraud/DeviceRisk.Infrastructure','backend/src/Fraud/DeviceRisk.Api','backend/tests/DeviceRisk.Scenarios','docs/specs/device-account-risk');$patterns=@('BEGIN PRIVATE KEY','BEGIN RSA PRIVATE KEY','github_pat_','ghp_','DEVICE_RISK_SECRET=','FRAUD_PROVIDER_SECRET=');$findings=@();foreach($root in $roots){if(!(Test-Path $root)){continue};Get-ChildItem $root -Recurse -File|Where-Object{$_.FullName-notmatch'\\(bin|obj)\\'}|ForEach-Object{foreach($p in $patterns){if(Select-String -Path $_.FullName -Pattern $p -SimpleMatch -ErrorAction SilentlyContinue){$findings+="$($_.FullName) -> $p"}}}};if($findings){$findings|ForEach-Object{Write-Host $_};throw 'Device risk secret scan failed.'};Write-Host 'Device risk secret scan PASS'